import sys, heapq
x = sys.stdin.read().split()
n = int(x[0])
lo, hi, out = [], [], []
for v in map(int, x[1:1 + n]):
    if not lo or v <= -lo[0]:
        heapq.heappush(lo, -v)
    else:
        heapq.heappush(hi, v)
    if len(lo) > len(hi) + 1:
        heapq.heappush(hi, -heapq.heappop(lo))
    elif len(hi) > len(lo):
        heapq.heappush(lo, -heapq.heappop(hi))
    out.append(-lo[0])
print(*out)

