import sys
x = sys.stdin.read().split()
k = int(x[0])
t = x[1:1 + k]
left, right, val = {}, {}, {}
val[0] = int(t[0])
queue, i = [0], 1
for node in queue:
    for side in (left, right):
        if i < k:
            if t[i] != "null":
                idx = len(val)
                val[idx] = int(t[i])
                side[node] = idx
                queue.append(idx)
            i += 1
ok = True
stack = [(0, None, None)]
while stack and ok:
    n, lo, hi = stack.pop()
    v = val[n]
    if (lo is not None and v <= lo) or (hi is not None and v >= hi):
        ok = False
    if n in left:
        stack.append((left[n], lo, v))
    if n in right:
        stack.append((right[n], v, hi))
print("VALID" if ok else "INVALID")

