m = [list(map(int, x[2 + i * n:2 + (i + 1) * n])) for i in range(n)]
def count_le(v):
    i, j, c = n - 1, 0, 0
    while i >= 0 and j < n:
        if m[i][j] <= v:
            c += i + 1
            j += 1
        else:
            i -= 1
    return c
lo, hi = m[0][0], m[-1][-1]
while lo < hi:
    mid = (lo + hi) // 2
    if count_le(mid) >= k:
        hi = mid
