from collections import deque
x = sys.stdin.read().split()
r, c = int(x[0]), int(x[1])
g = x[2:2 + r]
dist = [[-1] * c for _ in range(r)]
q = deque()
for i in range(r):
    for j in range(c):
        if g[i][j] == "0":
            dist[i][j] = 0
            q.append((i, j))
while q:
    i, j = q.popleft()
    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
        if 0 <= a < r and 0 <= b < c and dist[a][b] < 0:
            dist[a][b] = dist[i][j] + 1
            q.append((a, b))
print("\n".join(" ".join(map(str, row)) for row in dist))

